sheet = 'W0::Transition probabilities'
rows = data_rows(sheet, {'G':'number', 'H':'string', 'I':'string'})
trans = {}
for r in rows:
    p = num(sheet, f'G{r}')
    f = label(sheet, f'H{r}')
    t = label(sheet, f'I{r}')
    trans[(f, t)] = trans.get((f, t), 0.0) + p
states = ['Idle', 'Active', 'Done']
# step 0: Idle=1, others=0
dist = {'Idle': 1.0, 'Active': 0.0, 'Done': 0.0}
for step in range(4):
    new_dist = {'Idle': 0.0, 'Active': 0.0, 'Done': 0.0}
    for s in states:
        for t in states:
            prob = trans.get((s, t), 0.0)
            if s == 'Done' and t == 'Done':
                prob = 1.0
            elif s == 'Done':
                prob = 0.0 if s != t else 1.0
            new_dist[t] += dist[s] * prob
    dist = new_dist
result = round(dist['Done'], 6)

